INSERT INTO `news_translation` (`id`, `news_id`, `amh`, `orm`, `created_at`) VALUES
(4, 2, '{"title":"ዓመታዊ የጤና ገበያ ስኬት አስመዝግቧል","category":"ጤና","description":"ዓመታዊው የጤና ገበያ ከ500 በላይ ነዋሪዎችን አሳስቷል እነሱም ነጻ የጤና ፈተናዎችን እና የሕክምና አማካሪዎችን ተቀብለዋል።","shortDescription":""}', '{"title":"Gaaffii Fayyaa Waggaa Waggaa Milkaa''inaan Xumurame","category":"Fayyaa","description":"Gaaffii fayyaa waggaa waggaa jiraattota 500 ol ta''an kan fayyaa bilisaa fi gorsa qoricha argatanii gammachiise.","shortDescription":""}', '2025-12-19 09:54:23'),
(5, 3, '{"title":"የአካባቢ ትምህርት ቤት በአገር አቀፍ የሳይንስ ውድድር አሸንቷል","category":"ትምህርት","description":"ከልደታ ሁለተኛ ደረጃ ትምህርት ቤት የመጡ ተማሪዎች የአገር አቀፍ የሳይንስ ገበያ በአዲስ የሚቀይር ኃይል ፕሮጀክታቸው አሸንተዋል።","shortDescription":"የአካባቢ ተማሪዎች በአገር አቀፍ የሳይንስ ውድድር አሸንተዋል"}', '{"title":"Mana Barumsaa Naannoo Imalaan Walii Galtee Saayinsii Aangoo Itoophiyaa Irratti Mo''ate","category":"Barnoota","description":"Barattoonni mana barumsaa sadarkaa 2ffaa Lideta irraa ta''an imalaan qindeessaa humnaa guddisaa kan isaanii argatanii walii galtee saayinsii aangoo Itoophiyaa irratti mo''atan.","shortDescription":"Barattoonni naannoo walii galtee saayinsii aangoo Itoophiyaa irratti mo''atan"}', '2025-12-19 09:54:23'),
(6, 4, '{"title":"የመንገድ ግንባታ ፕሮጀክት ጀምሯል","category":"መሠረተ ልማት","description":"በክፍለ ከተማው ምዕራባዊ ክፍል ውስጥ ብዙ የሚጠበቀው የመንገድ ግንባታ ፕሮጀክት ጀምሯል፣ ይህም የትራፊክ ፍሰትን እንደሚያሻሽል ይጠበቃል።","short_description":"የመሠረተ ልማት ማሻሻያዎች በከተማዋ ምዕራባዊ ክፍል ጀምረዋል"}', '{"title":"Piroojektii Gidduu Karaa Jalqabame","category":"Bu''uura","description":"Piroojektii gidduu karaa kan seenaa magaalaa bahaatti baay''ee eegamu jalqabame, dhaabbata fiigaa garaagarummaa taasisee bu''aa fiigaa karaa fooyya''isu.","short_description":"Fooyya''insa bu''uuraa seenaa magaalaa bahaatti jalqabame"}', '2025-12-19 09:54:23'),
(7, 5, '{"title":"አዲስ የነፍሳት አስተዳደር ተቋም ተጀመረ","category":"አካባቢ","description":"በማህበረሰባችን ውስጥ የአካባቢ መቆያነትን ለማበረታታት አዲስ የማደራጀት ፕሮግራም ተጀምሯል።","short_description":"አዲሱ የማደራጀት ፕሮግራም የአካባቢ መቆያነትን ያበረታታል"}', '{"title":"Kaayyoo Gidduu Saaphanaa Haaraan Jalqabame","category":"Naannoo","description":"Pirograamiin irra deddeebi''ii haaraan hawaasa keenya keessatti taasisuu naannoo fooyya''isuuf jalqabame.","short_description":"Pirograamiin irra deddeebi''ii haaraa taasisuu naannoo gabbisuu dha"}', '2025-12-19 09:54:23'),
(8, 6, '{"title":"ልደታ አዲስ ዲጂታል አገልግሎት ማዕከል አስጀመረ","category":"ቴክኖሎጂ","description":"የልደታ ክፍለ ከተማ አስተዳደር እንደ መታወቂያ ሂደት፣ የግብር ጥያቄዎች እና የማህበረሰብ ማመልከቻዎች ያሉ አገልግሎቶችን ለማቅረብ የተነደፈ አዲስ ዲጂታል አገልግሎት ማዕከል አስጀምሯል።","short_description":"አዲሱ ዲጂታል አገልግሎት ማዕከል የከተማ አገልግሎቶችን ወደ ዜጎች ለማሻሻል ይረዳል"}', '{"title":"Lideta Giddugaleessa Tajaajilaa Dijitaalaa Haaraan Jalqabsiise","category":"Teknooloojii","description":"Bulchiinsa Lideta Sub-City giddugaleessa tajaajilaa dijitaalaa haaraan jalqabsiise, kan tajaajila akka hojii ID, gaafii kaffaltii, fi maddii hawaasaa akka tajaajilu qopheessee.","short_description":"Giddugaleessa tajaajilaa dijitaalaa haaraan dhaqqabaa tajaajila magaalaa jiraattotaaf fooyya''isa"}', '2025-12-19 09:54:23'),
(9, 7, '{"title":"ክፍለ ከተማ ትልቅ የመንገድ ጥገና ሥራ ጀምሯል","category":"መሠረተ ልማት","description":"በክፍለ ከተማው ውስጥ በብዙ ወረዳዎች የመንገድ ቁልቁልትን ለመጠገን እና ደህንነትን ለማሻሻል ትልቅ የመንገድ ጥገና ተቋም ጀምሯል።","short_description":"የመንገድ ጥገና ፕሮጀክት በብዙ ሰፈራዎች ጀምሯል"}', '{"title":"Sub-City''ichiin Hojii Guddaa Eegumsa Karaa Jalqabsiise","category":"Bu''uura","description":"Kaayyoo guddaan eegumsa karaa jalqabame akka qullubbii karaa hojjechuufi nagaa seenaa magaalaa keessatti fooyya''isuuf.","short_description":"Piroojektii eegumsa karaa seenaa magaalaa adda addaatti jalqabame"}', '2025-12-19 09:54:23'),
(10, 8, '{"title":"የአካባቢ ቤተ መጻሕፍት የወጣቶች ፕሮግራሞችን አስፋች","category":"ትምህርት","description":"የልደታ የህዝብ ቤተ መጻሕፍት የወጣቶች ፕሮግራሞቹን በአዲስ የማንበብ ክለቦች፣ ኮምፒውተር ዕውቀት ክፍሎች እና ቅዳሜ እና እሁድ የሥራ አውደ ማሰልጠኛዎች አስፋች።","short_description":"የወጣቶች ፕሮግራሞች በአዲስ የማንበብ እና ኮምፒውተር ክፍሎች ተሰፋፍተዋል"}', '{"title":"Mana Kitaaba Naannoo Daa''imman Pirograamota Isaa Daddabsiise","category":"Barnoota","description":"Mana kitaaba ummataa Lidetan pirograamota daa''immaa isaa daa''immaa barreeffama haaraa, kuusaa kompiitaraa, fi waaksii guyyaa taphaataatiin daddabsiise.","short_description":"Pirograamota daa''immaa daa''immaa barreeffama haaraafi kuusaa kompiitaraa wajjin daddabsiifame"}', '2025-12-19 09:54:23'),
(11, 9, '{"title":"የማህበረሰብ አትክልት ማሳደግ ተቋም እያደገ ነው","category":"አካባቢ","description":"የማህበረሰብ አትክልት ፕሮጀክት እየተራመደ ሲሄድ የአካባቢ ነዋሪዎች አትክልቶችን፣ ቅጠላ ቅጠሎችን እና አበቦችን በጋራ የህዝብ ቦታዎች ውስጥ ለመትከል በፈቃደኝነት አገልግለዋል።","short_description":"ነዋሪዎች የማህበረሰብ አትክልት ቦታዎችን ለማስፋፋት በፈቃደኝነት አገልግልተዋል"}', '{"title":"Kaayyoo Biqilaa Hawaasaa Itti Fufuu Eegale","category":"Naannoo","description":"Piroojektii biqilaa hawaasaatiin itti fufuu eegale jiraattoota naannoo fedhii wajjin biqiloota, utubaa, fi abaaboo''aa bakka ummataa waliin keessatti daddabsiisuuf hojjatan.","short_description":"Jiraattotni bakka biqilaa hawaasaa daddabsiisuuf fedhii wajjin hojjatan"}', '2025-12-19 09:54:23'),
(12, 10, '{"title":"ልደታ ዓመታዊ የንግድ መድረክ አካሄደ","category":"ንግድ","description":"ዓመታዊው የንግድ መድረክ ስለ ኢንቨስትመንት እድሎች እና ስለ አካባቢያዊ ኢኮኖሚያዊ እድገት ስትራቴጂዎች ለመወያየት ሰራተኞችን እና ባለሥልጣናትን አንድ ላይ አምጥቷል።","short_description":"የአካባቢ የንግድ መሪዎች ለእድገት ስትራቴጂዎች ለመወያየት ተሰብስበዋል"}', '{"title":"Lideta Murtii Daldalaa Waggaa Waggaa Taphate","category":"Daldala","description":"Murtiin daldalaa waggaa waggaa rakkoo daldalaa naannoo irratti mari''achuuf hojjattootaa fi dhaabbileen walitti qaban, carraa daldalaa naannoo fi strateejii guddisaa dhaqaa naannoo irratti mari''atan.","short_description":"Hoggantoota daldalaa naannoo wal ga''ii strateejii guddisaa irratti mari''achuuf walitti qaban"}', '2025-12-19 09:54:23'),
(13, 11, '{"title":"የህዝብ ፓርክ እድሳት ተጠናቋል","category":"ማህበረሰብ","description":"የማዕከላዊ የህዝብ ፓርክ እድሳት ተጠናቅቋል፣ ይህም አዳዲስ የመጫወቻ ቦታዎች፣ የእግረኛ መንገዶች እና የተሻሻለ መብራት ያካትታል።","short_description":"የማዕከላዊ የህዝብ ፓርክ ትልቅ እድሳት ተጠናቋል"}', '{"title":"Fuuldura Paarkii Ummataa Giddu Galeessaa Xumurame","category":"Hawaasaa","description":"Fuuldura paarkii ummataa giddu galeessaa xumurame, kan taphoota haaraa, karaa fiigaa, fi ifaa fooyya''aa qabu.","short_description":"Fuuldura guddaa paarkii ummataa giddu galeessaa xumurame"}', '2025-12-19 09:54:23'),
(15, 13, '{"title":"የወጣቶች የስፖርት ሊግ ጀምሯል","category":"ስፖርት","description":"የወጣቶች የስፖርት ሊግ በይፋ ጀምሯል፣ ይህም በፊት ቦሎ፣ በአትሌቲክስ እና በሌሎች እንቅስቃሴዎች ተሳትፎን ለማበረታታት እና ጤናማ ኑሮን ለማስተዋወቅ ያበረታታል።","short_description":"አዲሱ የወጣቶች የስፖርት ወቅት በፊት ቦሎ እና በአትሌቲክስ ውድድር ጀምሯል"}', '{"title":"Liigii Ispoortii Daa''immaa Jalqabame","category":"Isportii","description":"Liigiin ispoortii daa''immaa milkaa''inaan jalqabame, kubbaa miillaa, atileetikii, fi gochaalee biroo keessatti hirmaannaa dandeettii fayyaa qabu taasisuu dha.","short_description":"Tsiima ispoortii daa''immaa haaraan kubbaa miillaa fi atileetikii wajjin jalqabame"}', '2025-12-19 09:54:23'),
(24, 38, '{"title":"ልደታ ክፍለ ከተማ ዋና የመንገድ መሠረተ ልማት ማሻሻያ ሥራ ጀምሯል","category":"መሠረተ ልማት","description":"ልደታ ክፍለ ከተማ አስተዳደር 12 ቁልፍ ኮሪደሮችን ያካተተ ሁሉን አቀፍ የመንገድ ማሻሻያ ፕሮጀክት በይፋ ጀምሯል። ፕሮጀክቱ ከ300,000 በላይ ለሚሆኑ ነዋሪዎች ረጅም ጊዜ ሲዘልቁ የቆዩ የትራንስፖርት ችግሮችን ለመፍታት ያለመ ነው። ፕሮጀክቱ የሚያካትተው፡ መንገድ ማስፋፋት፣ ዘመናዊ የፍሳሽ ዝርጋታ ማስቀመጥ፣ የእግረኛ መንገዶችና የጎዳና ብርሃን ማሻሻያ ነው። ፕሮጀክቱ በ18 ወር ውስጥ ሙሉ ለሙሉ እንዲጠናቀቅ ሲጠበቅ ደረጃ አንድ በሚቀጥሉ ስድስት ወሮች ለቀረቦ ይሆናል።","short_description":"ልደታ ክፍለ ከተማ አስተዳደር 12 ቁልፍ ኮሪደሮችን ያካተተ ሁሉን አቀፍ የመንገድ ማሻሻያ ፕሮጀክት በይፋ ጀምሯል።"}', '{"title":"Bulchiinsa Kutaa Magaalaa Lideta Hojii Fooyya''insaa Daandii Gurguddaa Jalqabe","category":"Bu''uura","description":"Bulchiinsi Kutaa Magaalaa Lideta pirojektii fooyya''insaa daandii bal''aa koriidaroota gurguddaa 12 hammate ifa baase. Pirojektiin kun jiraattoota 300,000 ol qaban rakkoo geejjibaa waggaa dheeraa ture furuu kaayyoo godhatee jira. Pirojektiin kun babal''ina daandii, sirna dhangala''aa ammayyaa, karaa miilaa fi guddina ifa daandii ni hammata. Pirojektiin guutummaatti baatii 18 keessatti xumuramuu eegama; marsaa jalqabaa baatii jaha dhufurratti kennama.","short_description":"Bulchiinsi Kutaa Magaalaa Lideta pirojektii fooyya''insaa daandii bal''aa koriidaroota 12 hammate ifa baase."}', '2026-08-23 10:05:39'),
(25, 39, '{"title":"የነፃ ጤና ምርመራ ዘመቻ ከ15,000 በላይ ነዋሪዎችን ደርሷል","category":"ጤና","description":"ልደታ ክፍለ ከተማ የጤና ጽ/ቤት ሦስት ሳምንት ነፃ ጤና ምርመራ ዘመቻ ስኬታማ ሆኖ ጨርሷል። ዘመቻው በ8 የጤና ጣቢያዎች ከ15,000 በላይ ነዋሪዎችን አገልግሏል። የስኳር ህመም፣ ደም ግፊት፣ ሳንባ ነቀርሳ እና የእናቶች ጤና ምርመራ ሰጥቷል። ከ2,300 በላይ ነዋሪዎች ወደ ክትትል ሕክምና ተላልፈዋል፣ 450 የደም ግፊት ህሙማን ተለይተዋল። ተመሳሳይ ዘመቻዎች በሩብ ዓመት ይካሄዳሉ።","short_description":"ልደታ ክፍለ ከተማ የጤና ጽ/ቤት ሦስት ሳምንት የሚቆይ የነፃ ጤና ምርመራ ዘመቻ ጨርሷል፤ ከ15,000 በላይ ነዋሪዎችን አገልግሏል።"}', '{"title":"Kaadhimamni Qorannoo Fayyaa Bilisaa Jiraattota 15,000 Ol Ga''e","category":"Fayyaa","description":"Waajjirri Fayyaa Kutaa Magaalaa Lideta kaadhimama qorannoo fayyaa bilisaa torban sadii ture milkaa''inaan xumure. Wiirtuu fayyaa hawaasaa 8 keessatti jiraattoota 15,000 ol tajaajileera. Qorannoo dhibee sookoraa, dhiibbaa dhiigaa, TB fi fayyaa haadholii ni hammate. Jiraattoota 2,300 ol wal''aansa ittaansuuf ergaman; dhibee dhiibbaa dhiigaa hin beekkamne dura 450 adda bahan. Kaadhimamni fakkaataa rubu''aa waggaatti gaggeeffama.","short_description":"Waajjirri Fayyaa Kutaa Magaalaa Lideta wiirtuu fayyaa 8 keessatti jiraattoota 15,000 ol tajaajile."}', '2026-08-23 10:05:39'),
(26, 40, '{"title":"ሦስት አዳዲስ የመጀመሪያ ደረጃ ትምህርት ቤቶች ተከፈቱ","category":"ትምህርት","description":"ሦስት አዲስ ሙሉ ዝግጅት ያላቸው የመጀመሪያ ደረጃ ትምህርት ቤቶች በልደታ ክፍለ ከተማ ምርቃ ሥሯ ተከናወነ። 2,400 አዲስ ተማሪ ስፍራዎችን ጨምሮ ለዓመታት የቀጠለ የክፍሎቹ ጠባቢነት ችግር ያቃልላሉ። እያንዳንዱ ትምህርት ቤት ዘመናዊ ክፍሎች፣ ኮምፒውተር ላቦ፣ ቤተ-መጻሕፍትና ስፖርት ሜዳ ይዟል። ከትምህርት ቤቶቹ ምርቃ በኋላ ክፍለ ከተማው የተማሪ ወደ ክፍሎቹ ጥምርታ ከ65፡1 ወደ 45፡1 ተሻሽሏል።","short_description":"ሦስት አዲስ ሙሉ ዝግጅት ያላቸው የመጀመሪያ ደረጃ ትምህርት ቤቶች ተምሮ 2,400 አዲስ ተማሪ ስፍራዎች ጨምረዋል።"}', '{"title":"Mana Barumsaa Sadarkaa Tokkoffaa Haaraa Sadii Baname","category":"Barnoota","description":"Mana barumsaa sadarkaa tokkoffaa haaraa guutuu qophaa''e sadii kutaa magaalaa Lideta keessatti eebbifame. Teessoo barataa haaraa 2,400 dabaluun rakkoo xaxoo cufaa ta''u waggaa dheeraa miidhaa barnootarratti gahe hir''iseera. Manni barumsaa hundi kutaa ammayyaa, laaboraatoorii kompiyuutaraa, kuusaa kitaabaa fi dirree ispoortii qabaata. Kutaa magaalaa keessatti hir''ina barattoota kutaadhaaf jiru 65:1 irraa 45:1 gahuu odeeffateera.","short_description":"Mana barumsaa sadarkaa tokkoffaa haaraa guutuu qophaa''e sadii banameera; teessoo barataa haaraa 2,400 dabaluun rakkoo kutaa cufaa ta''u hir''ise."}', '2026-08-23 10:05:40'),
(27, 41, '{"title":"ልደታ ክፍለ ከተማ የቀበሌ ማህበረሰብ ምክክር መድረክ አዘጋጀ","category":"ክንውኖች","description":"ከ500 በላይ የማህበረሰብ መሪዎች፣ ወጣቶች ተወካዮች ና ነዋሪዎች ለሁለት ቀን ምክክር መድረክ ተሰበሰቡ። ምክክሩ ፓናል ውይይቶች፣ ሥራ ቡድኖች ና ክፍት ወለል ስብሰባዎች ያካትታል። ዋና ፍሬ ናቸው ካሏቸው ጉዳዮች አንዱ በሩብ ዓመት ተሰብስቦ ለአስተዳደሩ ምላሽ የሚሰጥ ቋሚ የማህበረሰብ አማካሪ ምክር ቤት ማቋቋም ነው። ሁሉም 10 ቀበሌዎች ተወካዮቻቸው ምክር ቤቱ ውስጥ ይኖሩዋቸዋል።","short_description":"ከ500 በላይ የማህበረሰብ መሪዎች፣ ወጣቶች ተወካዮችና ነዋሪዎች ለሁለት ቀን ምክክር መድረክ ተሳትፈዋል።"}', '{"title":"Kutaan Magaalaa Lideta Marii Hawaasaa Giddu-Galeessa Gaggeesse","category":"Taatee","description":"Hoggantoota hawaasaa fi jiraattoota kutaa magaalaa Lideta hundaa irraa dhufan 500 ol guyyaa lamaa mariif walitti qabaman. Marii kun marii garee paanelii, garee hojii fi taa''ichi barcuma banaa ni hammate. Bu''aa mariichaa ijoo keessaa tokko Koree Gorsa Hawaasaa Yeroo Hunda jiraatu hundeessuu waliigaluu ture. Kebeelee 10 hunda bakka bu''oota qabaatu.","short_description":"Hoggantoota hawaasaa, bakka bu''oota dargaggoota fi jiraattoota 500 ol marii guyyaa lama irratti argaman."}', '2026-08-23 10:05:40'),
(28, 42, '{"title":"አረንጓዴ ልደታ፡ 50,000 ዛፎች ተተክለዋል","category":"አካባቢ","description":"ልደታ ክፍለ ከተማ አስተዳደር \\"አረንጓዴ ልደታ\\" ቀጰ ሰርዷ ጀምሮ ከ3,000 በላይ ነዋሪዎች፣ ተማሪዎችና በጎ ፈቃደኞች ዓርብ ሳምንት ብቻ 50,000 ዛፎችን ፓርኮች፣ የጎዳና ዳርቻዎች ና ክፍት አረንጓዴ ቦታዎች ላይ ተክለዋል። ዋርካ፣ ቲዱ ና ፍሬ ሰጪ ዛፎች ዋና ዋና ዝርያዎቹ ናቸው። ለሚቀጥሉ ሁለት ዓመታት ክትትሎ ቡድኖች ወደ እያንዳንዱ ሥፍራ ይሰማሩ።","short_description":"ልደታ ክፍለ ከተማ \\"አረንጓዴ ልደታ\\" ቀጰ ሰርዷ ጀምሮ ነዋሪዎች እና በጎ ፈቃደኞች 50,000 ዛፎችን ተክለዋል።"}', '{"title":"Lideta Magariisaa: Muka 50,000 Dhaabame","category":"Naannoo","description":"Bulchiinsi Kutaa Magaalaa Lideta tarsiimoo naannoo seenaa qabeessa \\"Lideta Magariisaa\\" eebbise. Jiraattoota, barattootaa fi geengoo 3,000 ol hiriirsuun xandaa tokko qofaatti mooraa park, karaa fi bakka magariisaa banaarra muka 50,000 dhaabani. Warkaa, Tidhii fi muka firii kennuu kanneen filataman. Gaggeessitoota tajaajila kunuunsaa ganna lama dhufurratti kutaalee dhaabbii hunda irratti ramadama.","short_description":"Kutaan Magaalaa Lideta tarsiimoo \\"Lideta Magariisaa\\" eebbise; jiraattoota fi geengoo 3,000 ol hiriirsuun muka 50,000 dhaabe."}', '2026-08-23 10:05:43'),
(29, 43, '{"title":"ልደታ ክፍለ ከተማ ዲጂታሉ አገልግሎት ፖርታሉ ሥራ ጀምሯል","category":"ቴክኖሎጂ","description":"ልደታ ክፍለ ከተማ አስተዳደር ዲጂታሉ አገልግሎት ፖርታሉን ያስጀምሯ ሲሆን ነዋሪዎች 30 በላይ ማዘጋጃ አገልግሎቶችን ጽ/ቤቱን ሳይጎበኙ ኦንላይን ማግኘት ይችላሉ። ሥርዓቱ ዴስክቶፕና ሞባይሌ ተደራሽ ሆኖ በአማርኛ፣ ኦሮምኛ ና እንግሊዝኛ ያካሄዳል። አቅርቦ ያሉ አገልግሎቶች ናቸው፡ የንግድ ፈቃድ ታደሳ፣ የልደት ሰርቲፊኬት ና ቅሬታ ክትትሉ። ከ1,200 በላይ ነዋሪዎች ከጀምሮ በኋላ ባሉ ሳምንታት ምዝጋቧቸዋል።","short_description":"ነዋሪዎች አሁን ሰላሳ በላይ የማዘጋጃ አገልግሎቶችን ዲጂታሉ ፖርታሉ ጥቅም ላይ ሳያደርጉ ማድረግ ይችላሉ።"}', '{"title":"Portaalli Tajaajila Dijitaalaa Kutaa Magaalaa Lideta Hojii Jalqabe","category":"Teknooloojii","description":"Bulchiinsi Kutaa Magaalaa Lideta Portaalli Tajaajila Dijitaalaa eebbiseera. Jiraattonni tajaajila mootummaa 30 ol mana mootummaa deemuun alatti onlaayiniidhan argachuu ni danda''u. Sirni kun kompiyuutaraa fi moobayiliidhan dhaqqabamuu danda''uu Afaan Amaaraa, Afaan Oromoo fi Afaan Ingiliiziitiin ni hojjata. Tajaajilli haaromsa hayyama daldalaa, ragaa dhalootaa fi iyyannoo komii ni hammata. Jiraattoota 1,200 ol torbana jalqabaa keessatti galmeeffaman.","short_description":"Jiraattonni tajaajila mootummaa 30 ol portaalli dijitaalaa haaraa fayyadamuudhaan mana mootummaa dhaquu malee argachuu danda''u."}', '2026-08-23 10:05:44'),
(30, 44, '{"title":"ክፍለ ከተማ አስተዳደሩ ህገ-ወጥ ሕንፃ ግንባታ ላይ ጠንከረ","category":"ደህንነት","description":"ልደታ ክፍለ ከተማ አስተዳደር ህገ-ወጥ ሕንፃዎችን ለማፍረስ ዘጠኝ ሳምንት ዘመቻ ካካሄደ 47 ህገ-ወጥ ሕንፃ ፈርሶ 120 ባለ ንብረቶት ማስጠንቀቂያ ተሰጣቸው። ሕንፃዎቹ ዋና ዋናዎቹ ናቸው፡ ፈቃድ ሳይወሰዱ ያሳቆሩ ሕንፃዎችና የሕዝብ ቦታ ወረራዎች። ሕጋዊ ፈቃድ ከማውጣት ሳይጀምሩ ሕንፃ ለሚሰሩ ሁሉ ነፃ ምክር ይሰጣል።","short_description":"ልደታ ክፍለ ከተማ 47 ህገ-ወጥ ሕንፃዎችን አፍርሶ 120 ባለ ንብረቶችን ማስጠንቀቂያ ሰጠ።"}', '{"title":"Bulchiinsi Kutaa Magaalaa Ijaarsaa Seeraan Alaa Irratti Jabaate","category":"Nagaa","description":"Tarkaanfii murteessaa ta''een Bulchiinsi Kutaa Magaalaa Lideta wiirtuu torban jahaa ijaarsaa seeraan alaa 47 diigee abbaa qabeenya dabalataa 120 tti beeksisa ergite. Ijaarsaaleen kun carraa daandii uummataa seenuun dhuunfataman, mana hayyama malee ijaaraman ni hammatu. Abbaa qabeenyaa tarree kenname keessatti ijaarsa seeraan alaa of-danda''an diigan adabbii dabalataa hin argatan.","short_description":"Kutaan Magaalaa Lideta ijaarsa seeraan alaa 47 diigee, abbaa qabeenya 120 tti ajaja ergite."}', '2026-08-23 10:05:44'),
(31, 45, '{"title":"የወጣቶች ክህሎት ማሰልጠኛ ማዕከል 800 ወጣቶችን ምዝጋቧል","category":"ትምህርት","description":"ልደታ ክፍለ ከተማ ወጣቶችና ስፖርት ጽ/ቤት ከ18 እስከ 35 ዓመት 800 ወጣቶችን ቅርብ ሙያ ክህሎት ሥልጠናዎች ምዝጋቧቸዋል። ሥልጠናው ኢንፎርሜሽን ቴክኖሎጂ፣ ስፌት ፋሽን ዲዛይን ና ሸክምና ምሰሶ ሥራ ያካትታል። ፕሮግራሙ ምሩቃን ለ70% ሥራ ያቀርቧቸዋል። ቀጣዩ ዙር ምዝገባ ቅድሚያ ለሴቶች፣ አካል ጉዳተኞችና ዝቅተኛ ቤተሰቦቻቸው ሕፃናት ተሰጥቷቸዋል።","short_description":"ልደታ ክፍለ ከተማ ወጣቶች ጽ/ቤት 800 ወጣቶችን የሙያ ክህሎት ሥልጠናዎች ምዝጋቧቸዋል።"}', '{"title":"Wiirtuu Leenjii Dandeettii Dargaggoota 800 Galmeesse","category":"Barnoota","description":"Waajjirri Dargaggoota fi Ispoortii Kutaa Magaalaa Lideta dargaggoo waggaa 18 hanga 35 ta''an 800 sagantaa leenjii dandeettii ogummaa haaraadhaaf galmeesseera. Leenjiin IT, uffata ho''isuu fi ijaarsa ni hammata. Sagantaan kana dura dhibbeentaa 70 ol hojii argatan. Galmeessa wiirtuu itti aanuuf dursa dubartootaa, qaamni miidhameefi maatii galii gadi-aanaa qabaniif kenname.","short_description":"Waajjirri Dargaggoota Kutaa Magaalaa Lideta dargaggoo 800 sagantaa leenjii dandeettii ogummaa haaraadhaf galmeesse."}', '2026-08-23 10:05:45'),
(32, 46, '{"title":"ታደሰው ልደታ ዋናው ገበያ ለነጋዴዎችና ሕዝብ ተከፈተ","category":"መሠረተ ልማት","description":"14 ወር ከፍተኛ ግንባታ ካለቀ በኋላ ሙሉ ታደሰው ልደታ ዋናው ገበያ ለነጋዴዎችና ሕዝብ ተከፈተ። ፕሮጀክቱ ጠባቡ ጥፍ ባዩ ገበያ ከ800 ቋሚ ሱቆቹ ቁጥር ያለ ዘመናዊ ቦታ ወደ ቀይሮታል። ፍሬ ጥቁር ወርቅ፣ ለብሰው ኢሌክትሮኒክስ ና ምግብ አገልግሎት ልዩ ቦታዎቹ ናቸው። ዋናዋ ቆሻሻ አወጋገድ ሥርዓት፣ ሳኒቴሽን ሕዳጎቻ ና CCTV ክትትሉ ፍሬዎቹ ናቸው።","short_description":"14 ወር ግንባታ ካለቀ በኋላ ሙሉ ታደሰው ልደታ ዋናው ገበያ ዘመናዊ ሱቆቹ ሳኒቴሽን ና የእሳት ደህንነት ሥርዓቶቹ ጋር ተከፈተ።"}', '{"title":"Gabatee Giddugaleessa Lideta Haaromsame Daldaltoota fi Uummataaf Baname","category":"Bu''uura","description":"Gabatee Giddugaleessa Lideta erga ijaarsi cimaa baatii 14 erga xumuramee booda daldaltoota fi uummataaf itti banameera. Pirojektiin haaromsaa gabatee cufaa mancaa''aa ture gara wiirtuu daldala ammayyaa teessoo bantii 800 ol qabu jijjiire. Naannoo addaa oomisha qilleensa qabate, uffata, elektirooniksi fi tajaajila nyaataaf; sirna bulchiinsa qotiyyoo fi to''annoo CCTV ni hammatu.","short_description":"Gabatee Giddugaleessa Lideta baatii 14 ijaaramee guutummaatti haaromsamee bantii ammayyaa waliin banameera."}', '2026-08-23 10:05:45'),
(33, 47, '{"title":"ልደታ ክፍለ ከተማ ለሕዝብ አገልግሎት ዕጽዋ ሽልማት ተቀበለ","category":"ክንውኖች","description":"ልደታ ክፍለ ከተማ አስተዳደር ለሁለተኛ ተከታይ ዓመት የአዲስ አበባ ከተማ አስተዳደር ምርጥ ሕዝብ አገልግሎት ሽልማት ተቀበለ። ሽልማቱ ሕዝብ አገልግሎት ጥራት፣ ዜጎች እርካታ ና አስተዳደር ግልፅነት ወቅታዊ አፈፃፀምን ይሸልማል። ሽልሙ ዓመታዊ ጉባኤ ላይ ቀርቦ ልደታ የጉዳይ ጊዜ 42% ቀንሷል፣ ዜጎች ዕርካታ 87% ደርሷል ና ዲጂታሉ ቅሬታ ምስሪት ሙሉ ቀርቦ ሥራ ላይ ሆኗ።","short_description":"ልደታ ክፍለ ከተማ አስተዳደር ለሁለተኛ ተከታይ ዓመት የአዲስ አበባ ምርጥ ሕዝብ አገልግሎት ሽልማት ተቀበለ።"}', '{"title":"Kutaan Magaalaa Lideta Badhaasa Qulqullina Tajaajila Uummataa Fudhate","category":"Taatee","description":"Bulchiinsi Kutaa Magaalaa Lideta Badhaasa Qulqullina Tajaajila Uummataa Bulchiinsa Magaalaa Finfinnee waggaa lammataaf wal-duraa duubaan fudhate. Tajaajila qulqullina, gammachuu lammii fi iftoominaa bulchiinsaatiin raawwii ol''aanaa agarsiise. Badhaasni milkaa''ina Lideta eeruun: yeroo eeggannaa tajaajilaa giddu-galeessaa dhibbeentaa 42tiin hir''isuu, lammiidhaan maxxanfame dhibbeentaa 87 ta''uun, fi sirna bulchiinsa komii dijitaalaa guutummaatti hojjetu hojiirra oolchuun.","short_description":"Bulchiinsi Kutaa Magaalaa Lideta Badhaasa Qulqullina Tajaajila Uummataa waggaa lammataaf wal-duraa duubaan fudhate."}', '2026-08-23 10:05:47'),
(34, 28, '{"title":"ልደታ ክፍለ ከተማ ዋና የመንገድ መሠረተ ልማት ማሻሻያ ሥራ ጀምሯል","category":"መሠረተ ልማት","description":"ልደታ ክፍለ ከተማ አስተዳደር 12 ቁልፍ ኮሪደሮችን ያካተተ ሁሉን አቀፍ የመንገድ ማሻሻያ ፕሮጀክት በይፋ ጀምሯል። ፕሮጀክቱ ከ300,000 በላይ ለሚሆኑ ነዋሪዎች ረጅም ጊዜ ሲዘልቁ የቆዩ የትራንስፖርት ችግሮችን ለመፍታት ያለመ ነው። ፕሮጀክቱ የሚያካትተው፡ መንገድ ማስፋፋት፣ ዘመናዊ የፍሳሽ ዝርጋታ ማስቀመጥ፣ የእግረኛ መንገዶችና የጎዳና ብርሃን ማሻሻያ ነው። ፕሮጀክቱ በ18 ወር ውስጥ ሙሉ ለሙሉ እንዲጠናቀቅ ሲጠበቅ ደረጃ አንድ በሚቀጥሉ ስድስት ወሮች ለቀረቦ ይሆናል።","short_description":"ልደታ ክፍለ ከተማ አስተዳደር 12 ቁልፍ ኮሪደሮችን ያካተተ ሁሉን አቀፍ የመንገድ ማሻሻያ ፕሮጀክት በይፋ ጀምሯል።"}', '{"title":"Bulchiinsa Kutaa Magaalaa Lideta Hojii Fooyya''insaa Daandii Gurguddaa Jalqabe","category":"Bu''uura","description":"Bulchiinsi Kutaa Magaalaa Lideta pirojektii fooyya''insaa daandii bal''aa koriidaroota gurguddaa 12 hammate ifa baase. Pirojektiin kun jiraattoota 300,000 ol qaban rakkoo geejjibaa waggaa dheeraa ture furuu kaayyoo godhatee jira. Pirojektiin kun babal''ina daandii, sirna dhangala''aa ammayyaa, karaa miilaa fi guddina ifa daandii ni hammata. Pirojektiin guutummaatti baatii 18 keessatti xumuramuu eegama; marsaa jalqabaa baatii jaha dhufurratti kennama.","short_description":"Bulchiinsi Kutaa Magaalaa Lideta pirojektii fooyya''insaa daandii bal''aa koriidaroota 12 hammate ifa baase."}', '2026-08-23 11:30:12'),
(35, 29, '{"title":"የነፃ ጤና ምርመራ ዘመቻ ከ15,000 በላይ ነዋሪዎችን ደርሷል","category":"ጤና","description":"ልደታ ክፍለ ከተማ የጤና ጽ/ቤት ሦስት ሳምንት ነፃ ጤና ምርመራ ዘመቻ ስኬታማ ሆኖ ጨርሷል። ዘመቻው በ8 የጤና ጣቢያዎች ከ15,000 በላይ ነዋሪዎችን አገልግሏል። የስኳር ህመም፣ ደም ግፊት፣ ሳንባ ነቀርሳ እና የእናቶች ጤና ምርመራ ሰጥቷል። ከ2,300 በላይ ነዋሪዎች ወደ ክትትል ሕክምና ተላልፈዋል፣ 450 የደም ግፊት ህሙማን ተለይተዋল። ተመሳሳይ ዘመቻዎች በሩብ ዓመት ይካሄዳሉ።","short_description":"ልደታ ክፍለ ከተማ የጤና ጽ/ቤት ሦስት ሳምንት የሚቆይ የነፃ ጤና ምርመራ ዘመቻ ጨርሷል፤ ከ15,000 በላይ ነዋሪዎችን አገልግሏል።"}', '{"title":"Kaadhimamni Qorannoo Fayyaa Bilisaa Jiraattota 15,000 Ol Ga''e","category":"Fayyaa","description":"Waajjirri Fayyaa Kutaa Magaalaa Lideta kaadhimama qorannoo fayyaa bilisaa torban sadii ture milkaa''inaan xumure. Wiirtuu fayyaa hawaasaa 8 keessatti jiraattoota 15,000 ol tajaajileera. Qorannoo dhibee sookoraa, dhiibbaa dhiigaa, TB fi fayyaa haadholii ni hammate. Jiraattoota 2,300 ol wal''aansa ittaansuuf ergaman; dhibee dhiibbaa dhiigaa hin beekkamne dura 450 adda bahan. Kaadhimamni fakkaataa rubu''aa waggaatti gaggeeffama.","short_description":"Waajjirri Fayyaa Kutaa Magaalaa Lideta wiirtuu fayyaa 8 keessatti jiraattoota 15,000 ol tajaajile."}', '2026-08-23 11:30:13'),
(36, 30, '{"title":"ሦስት አዳዲስ የመጀመሪያ ደረጃ ትምህርት ቤቶች ተከፈቱ","category":"ትምህርት","description":"ሦስት አዲስ ሙሉ ዝግጅት ያላቸው የመጀመሪያ ደረጃ ትምህርት ቤቶች በልደታ ክፍለ ከተማ ምርቃ ሥሯ ተከናወነ። 2,400 አዲስ ተማሪ ስፍራዎችን ጨምሮ ለዓመታት የቀጠለ የክፍሎቹ ጠባቢነት ችግር ያቃልላሉ። እያንዳንዱ ትምህርት ቤት ዘመናዊ ክፍሎች፣ ኮምፒውተር ላቦ፣ ቤተ-መጻሕፍትና ስፖርት ሜዳ ይዟል። ከትምህርት ቤቶቹ ምርቃ በኋላ ክፍለ ከተማው የተማሪ ወደ ክፍሎቹ ጥምርታ ከ65፡1 ወደ 45፡1 ተሻሽሏል።","short_description":"ሦስት አዲስ ሙሉ ዝግጅት ያላቸው የመጀመሪያ ደረጃ ትምህርት ቤቶች ተምሮ 2,400 አዲስ ተማሪ ስፍራዎች ጨምረዋል።"}', '{"title":"Mana Barumsaa Sadarkaa Tokkoffaa Haaraa Sadii Baname","category":"Barnoota","description":"Mana barumsaa sadarkaa tokkoffaa haaraa guutuu qophaa''e sadii kutaa magaalaa Lideta keessatti eebbifame. Teessoo barataa haaraa 2,400 dabaluun rakkoo xaxoo cufaa ta''u waggaa dheeraa miidhaa barnootarratti gahe hir''iseera. Manni barumsaa hundi kutaa ammayyaa, laaboraatoorii kompiyuutaraa, kuusaa kitaabaa fi dirree ispoortii qabaata. Kutaa magaalaa keessatti hir''ina barattoota kutaadhaaf jiru 65:1 irraa 45:1 gahuu odeeffateera.","short_description":"Mana barumsaa sadarkaa tokkoffaa haaraa guutuu qophaa''e sadii banameera; teessoo barataa haaraa 2,400 dabaluun rakkoo kutaa cufaa ta''u hir''ise."}', '2026-08-23 11:30:14'),
(37, 31, '{"title":"ልደታ ክፍለ ከተማ የቀበሌ ማህበረሰብ ምክክር መድረክ አዘጋጀ","category":"ክንውኖች","description":"ከ500 በላይ የማህበረሰብ መሪዎች፣ ወጣቶች ተወካዮች ና ነዋሪዎች ለሁለት ቀን ምክክር መድረክ ተሰበሰቡ። ምክክሩ ፓናል ውይይቶች፣ ሥራ ቡድኖች ና ክፍት ወለል ስብሰባዎች ያካትታል። ዋና ፍሬ ናቸው ካሏቸው ጉዳዮች አንዱ በሩብ ዓመት ተሰብስቦ ለአስተዳደሩ ምላሽ የሚሰጥ ቋሚ የማህበረሰብ አማካሪ ምክር ቤት ማቋቋም ነው። ሁሉም 10 ቀበሌዎች ተወካዮቻቸው ምክር ቤቱ ውስጥ ይኖሩዋቸዋል።","short_description":"ከ500 በላይ የማህበረሰብ መሪዎች፣ ወጣቶች ተወካዮችና ነዋሪዎች ለሁለት ቀን ምክክር መድረክ ተሳትፈዋል።"}', '{"title":"Kutaan Magaalaa Lideta Marii Hawaasaa Giddu-Galeessa Gaggeesse","category":"Taatee","description":"Hoggantoota hawaasaa fi jiraattoota kutaa magaalaa Lideta hundaa irraa dhufan 500 ol guyyaa lamaa mariif walitti qabaman. Marii kun marii garee paanelii, garee hojii fi taa''ichi barcuma banaa ni hammate. Bu''aa mariichaa ijoo keessaa tokko Koree Gorsa Hawaasaa Yeroo Hunda jiraatu hundeessuu waliigaluu ture. Kebeelee 10 hunda bakka bu''oota qabaatu.","short_description":"Hoggantoota hawaasaa, bakka bu''oota dargaggoota fi jiraattoota 500 ol marii guyyaa lama irratti argaman."}', '2026-08-23 11:30:15');
INSERT INTO `news_translation` (`id`, `news_id`, `amh`, `orm`, `created_at`) VALUES
(38, 32, '{"title":"አረንጓዴ ልደታ፡ 50,000 ዛፎች ተተክለዋል","category":"አካባቢ","description":"ልደታ ክፍለ ከተማ አስተዳደር \\"አረንጓዴ ልደታ\\" ቀጰ ሰርዷ ጀምሮ ከ3,000 በላይ ነዋሪዎች፣ ተማሪዎችና በጎ ፈቃደኞች ዓርብ ሳምንት ብቻ 50,000 ዛፎችን ፓርኮች፣ የጎዳና ዳርቻዎች ና ክፍት አረንጓዴ ቦታዎች ላይ ተክለዋል። ዋርካ፣ ቲዱ ና ፍሬ ሰጪ ዛፎች ዋና ዋና ዝርያዎቹ ናቸው። ለሚቀጥሉ ሁለት ዓመታት ክትትሎ ቡድኖች ወደ እያንዳንዱ ሥፍራ ይሰማሩ።","short_description":"ልደታ ክፍለ ከተማ \\"አረንጓዴ ልደታ\\" ቀጰ ሰርዷ ጀምሮ ነዋሪዎች እና በጎ ፈቃደኞች 50,000 ዛፎችን ተክለዋል።"}', '{"title":"Lideta Magariisaa: Muka 50,000 Dhaabame","category":"Naannoo","description":"Bulchiinsi Kutaa Magaalaa Lideta tarsiimoo naannoo seenaa qabeessa \\"Lideta Magariisaa\\" eebbise. Jiraattoota, barattootaa fi geengoo 3,000 ol hiriirsuun xandaa tokko qofaatti mooraa park, karaa fi bakka magariisaa banaarra muka 50,000 dhaabani. Warkaa, Tidhii fi muka firii kennuu kanneen filataman. Gaggeessitoota tajaajila kunuunsaa ganna lama dhufurratti kutaalee dhaabbii hunda irratti ramadama.","short_description":"Kutaan Magaalaa Lideta tarsiimoo \\"Lideta Magariisaa\\" eebbise; jiraattoota fi geengoo 3,000 ol hiriirsuun muka 50,000 dhaabe."}', '2026-08-23 11:30:18'),
(39, 33, '{"title":"ልደታ ክፍለ ከተማ ዲጂታሉ አገልግሎት ፖርታሉ ሥራ ጀምሯል","category":"ቴክኖሎጂ","description":"ልደታ ክፍለ ከተማ አስተዳደር ዲጂታሉ አገልግሎት ፖርታሉን ያስጀምሯ ሲሆን ነዋሪዎች 30 በላይ ማዘጋጃ አገልግሎቶችን ጽ/ቤቱን ሳይጎበኙ ኦንላይን ማግኘት ይችላሉ። ሥርዓቱ ዴስክቶፕና ሞባይሌ ተደራሽ ሆኖ በአማርኛ፣ ኦሮምኛ ና እንግሊዝኛ ያካሄዳል። አቅርቦ ያሉ አገልግሎቶች ናቸው፡ የንግድ ፈቃድ ታደሳ፣ የልደት ሰርቲፊኬት ና ቅሬታ ክትትሉ። ከ1,200 በላይ ነዋሪዎች ከጀምሮ በኋላ ባሉ ሳምንታት ምዝጋቧቸዋል።","short_description":"ነዋሪዎች አሁን ሰላሳ በላይ የማዘጋጃ አገልግሎቶችን ዲጂታሉ ፖርታሉ ጥቅም ላይ ሳያደርጉ ማድረግ ይችላሉ።"}', '{"title":"Portaalli Tajaajila Dijitaalaa Kutaa Magaalaa Lideta Hojii Jalqabe","category":"Teknooloojii","description":"Bulchiinsi Kutaa Magaalaa Lideta Portaalli Tajaajila Dijitaalaa eebbiseera. Jiraattonni tajaajila mootummaa 30 ol mana mootummaa deemuun alatti onlaayiniidhan argachuu ni danda''u. Sirni kun kompiyuutaraa fi moobayiliidhan dhaqqabamuu danda''uu Afaan Amaaraa, Afaan Oromoo fi Afaan Ingiliiziitiin ni hojjata. Tajaajilli haaromsa hayyama daldalaa, ragaa dhalootaa fi iyyannoo komii ni hammata. Jiraattoota 1,200 ol torbana jalqabaa keessatti galmeeffaman.","short_description":"Jiraattonni tajaajila mootummaa 30 ol portaalli dijitaalaa haaraa fayyadamuudhaan mana mootummaa dhaquu malee argachuu danda''u."}', '2026-08-23 11:30:19'),
(40, 34, '{"title":"ክፍለ ከተማ አስተዳደሩ ህገ-ወጥ ሕንፃ ግንባታ ላይ ጠንከረ","category":"ደህንነት","description":"ልደታ ክፍለ ከተማ አስተዳደር ህገ-ወጥ ሕንፃዎችን ለማፍረስ ዘጠኝ ሳምንት ዘመቻ ካካሄደ 47 ህገ-ወጥ ሕንፃ ፈርሶ 120 ባለ ንብረቶት ማስጠንቀቂያ ተሰጣቸው። ሕንፃዎቹ ዋና ዋናዎቹ ናቸው፡ ፈቃድ ሳይወሰዱ ያሳቆሩ ሕንፃዎችና የሕዝብ ቦታ ወረራዎች። ሕጋዊ ፈቃድ ከማውጣት ሳይጀምሩ ሕንፃ ለሚሰሩ ሁሉ ነፃ ምክር ይሰጣል።","short_description":"ልደታ ክፍለ ከተማ 47 ህገ-ወጥ ሕንፃዎችን አፍርሶ 120 ባለ ንብረቶችን ማስጠንቀቂያ ሰጠ።"}', '{"title":"Bulchiinsi Kutaa Magaalaa Ijaarsaa Seeraan Alaa Irratti Jabaate","category":"Nagaa","description":"Tarkaanfii murteessaa ta''een Bulchiinsi Kutaa Magaalaa Lideta wiirtuu torban jahaa ijaarsaa seeraan alaa 47 diigee abbaa qabeenya dabalataa 120 tti beeksisa ergite. Ijaarsaaleen kun carraa daandii uummataa seenuun dhuunfataman, mana hayyama malee ijaaraman ni hammatu. Abbaa qabeenyaa tarree kenname keessatti ijaarsa seeraan alaa of-danda''an diigan adabbii dabalataa hin argatan.","short_description":"Kutaan Magaalaa Lideta ijaarsa seeraan alaa 47 diigee, abbaa qabeenya 120 tti ajaja ergite."}', '2026-08-23 11:30:20'),
(41, 35, '{"title":"የወጣቶች ክህሎት ማሰልጠኛ ማዕከል 800 ወጣቶችን ምዝጋቧል","category":"ትምህርት","description":"ልደታ ክፍለ ከተማ ወጣቶችና ስፖርት ጽ/ቤት ከ18 እስከ 35 ዓመት 800 ወጣቶችን ቅርብ ሙያ ክህሎት ሥልጠናዎች ምዝጋቧቸዋል። ሥልጠናው ኢንፎርሜሽን ቴክኖሎጂ፣ ስፌት ፋሽን ዲዛይን ና ሸክምና ምሰሶ ሥራ ያካትታል። ፕሮግራሙ ምሩቃን ለ70% ሥራ ያቀርቧቸዋል። ቀጣዩ ዙር ምዝገባ ቅድሚያ ለሴቶች፣ አካል ጉዳተኞችና ዝቅተኛ ቤተሰቦቻቸው ሕፃናት ተሰጥቷቸዋል።","short_description":"ልደታ ክፍለ ከተማ ወጣቶች ጽ/ቤት 800 ወጣቶችን የሙያ ክህሎት ሥልጠናዎች ምዝጋቧቸዋል።"}', '{"title":"Wiirtuu Leenjii Dandeettii Dargaggoota 800 Galmeesse","category":"Barnoota","description":"Waajjirri Dargaggoota fi Ispoortii Kutaa Magaalaa Lideta dargaggoo waggaa 18 hanga 35 ta''an 800 sagantaa leenjii dandeettii ogummaa haaraadhaaf galmeesseera. Leenjiin IT, uffata ho''isuu fi ijaarsa ni hammata. Sagantaan kana dura dhibbeentaa 70 ol hojii argatan. Galmeessa wiirtuu itti aanuuf dursa dubartootaa, qaamni miidhameefi maatii galii gadi-aanaa qabaniif kenname.","short_description":"Waajjirri Dargaggoota Kutaa Magaalaa Lideta dargaggoo 800 sagantaa leenjii dandeettii ogummaa haaraadhaf galmeesse."}', '2026-08-23 11:30:20'),
(42, 36, '{"title":"ታደሰው ልደታ ዋናው ገበያ ለነጋዴዎችና ሕዝብ ተከፈተ","category":"መሠረተ ልማት","description":"14 ወር ከፍተኛ ግንባታ ካለቀ በኋላ ሙሉ ታደሰው ልደታ ዋናው ገበያ ለነጋዴዎችና ሕዝብ ተከፈተ። ፕሮጀክቱ ጠባቡ ጥፍ ባዩ ገበያ ከ800 ቋሚ ሱቆቹ ቁጥር ያለ ዘመናዊ ቦታ ወደ ቀይሮታል። ፍሬ ጥቁር ወርቅ፣ ለብሰው ኢሌክትሮኒክስ ና ምግብ አገልግሎት ልዩ ቦታዎቹ ናቸው። ዋናዋ ቆሻሻ አወጋገድ ሥርዓት፣ ሳኒቴሽን ሕዳጎቻ ና CCTV ክትትሉ ፍሬዎቹ ናቸው።","short_description":"14 ወር ግንባታ ካለቀ በኋላ ሙሉ ታደሰው ልደታ ዋናው ገበያ ዘመናዊ ሱቆቹ ሳኒቴሽን ና የእሳት ደህንነት ሥርዓቶቹ ጋር ተከፈተ።"}', '{"title":"Gabatee Giddugaleessa Lideta Haaromsame Daldaltoota fi Uummataaf Baname","category":"Bu''uura","description":"Gabatee Giddugaleessa Lideta erga ijaarsi cimaa baatii 14 erga xumuramee booda daldaltoota fi uummataaf itti banameera. Pirojektiin haaromsaa gabatee cufaa mancaa''aa ture gara wiirtuu daldala ammayyaa teessoo bantii 800 ol qabu jijjiire. Naannoo addaa oomisha qilleensa qabate, uffata, elektirooniksi fi tajaajila nyaataaf; sirna bulchiinsa qotiyyoo fi to''annoo CCTV ni hammatu.","short_description":"Gabatee Giddugaleessa Lideta baatii 14 ijaaramee guutummaatti haaromsamee bantii ammayyaa waliin banameera."}', '2026-08-23 11:30:21'),
(43, 37, '{"title":"ልደታ ክፍለ ከተማ ለሕዝብ አገልግሎት ዕጽዋ ሽልማት ተቀበለ","category":"ክንውኖች","description":"ልደታ ክፍለ ከተማ አስተዳደር ለሁለተኛ ተከታይ ዓመት የአዲስ አበባ ከተማ አስተዳደር ምርጥ ሕዝብ አገልግሎት ሽልማት ተቀበለ። ሽልማቱ ሕዝብ አገልግሎት ጥራት፣ ዜጎች እርካታ ና አስተዳደር ግልፅነት ወቅታዊ አፈፃፀምን ይሸልማል። ሽልሙ ዓመታዊ ጉባኤ ላይ ቀርቦ ልደታ የጉዳይ ጊዜ 42% ቀንሷል፣ ዜጎች ዕርካታ 87% ደርሷል ና ዲጂታሉ ቅሬታ ምስሪት ሙሉ ቀርቦ ሥራ ላይ ሆኗ።","short_description":"ልደታ ክፍለ ከተማ አስተዳደር ለሁለተኛ ተከታይ ዓመት የአዲስ አበባ ምርጥ ሕዝብ አገልግሎት ሽልማት ተቀበለ።"}', '{"title":"Kutaan Magaalaa Lideta Badhaasa Qulqullina Tajaajila Uummataa Fudhate","category":"Taatee","description":"Bulchiinsi Kutaa Magaalaa Lideta Badhaasa Qulqullina Tajaajila Uummataa Bulchiinsa Magaalaa Finfinnee waggaa lammataaf wal-duraa duubaan fudhate. Tajaajila qulqullina, gammachuu lammii fi iftoominaa bulchiinsaatiin raawwii ol''aanaa agarsiise. Badhaasni milkaa''ina Lideta eeruun: yeroo eeggannaa tajaajilaa giddu-galeessaa dhibbeentaa 42tiin hir''isuu, lammiidhaan maxxanfame dhibbeentaa 87 ta''uun, fi sirna bulchiinsa komii dijitaalaa guutummaatti hojjetu hojiirra oolchuun.","short_description":"Bulchiinsi Kutaa Magaalaa Lideta Badhaasa Qulqullina Tajaajila Uummataa waggaa lammataaf wal-duraa duubaan fudhate."}', '2026-08-23 11:30:22');
